// src/verbs/fixtures/pr_ready.golden-scenarios.ts -- the NOT-OPTED-IN scenarios of the
// version-collision ruling (zheref/nen#663), driven through `prReady` exactly
// as ../pr_ready.test.ts drives it (its stubSource/stubDeps, copied here
// verbatim), so the SAME file can run on origin/main to produce goldens and on
// this branch to compare against them byte for byte.
//
// MAIN-COMPATIBLE ON PURPOSE. It imports only what origin/main already
// exports, and nothing about version collisions: the goldens under
// ./non-opted-in-main/ were generated by copying this file, unchanged, to the
// same path in a detached origin/main worktree (that directory's README names
// the commit). It lives under fixtures/ because it carries the fixture's
// reviewer logins, as ../pr_ready.test.ts does. Fictional throughout: the
// repository is `acme/widget`.

import { readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { prReady, type Io, type PrReadyDeps, type PrReadyInput } from "../pr_ready.js";
import type { PrRef, PrStateSource } from "../../github/pr_state.js";
import type { CheckRollupPage, PullRequestSnapshot, ReviewRequestsPage, ReviewThreadPage } from "../../github/graphql.js";
import { BANKAI_REPO } from "../../schema/fixtures/paths.js";
import { GATES_FILE, schemaPath } from "../../schema/source.js";
import { VERSION } from "../../version.js";
import { makeTempDir } from "../../testing/tempdir.js";

// ── ../pr_ready.test.ts's harness, verbatim but for the overrides' reach ─────

function stubSource(overrides: Partial<PrStateSource> = {}, snapshotOverrides: Partial<PullRequestSnapshot> = {}): PrStateSource {
  const snapshot: PullRequestSnapshot = {
    pullRequest: {
      state: "OPEN",
      number: 9,
      mergeable: "MERGEABLE",
      isDraft: false,
      headRefOid: "cafebabe",
      headRefName: "feature/x",
      baseRefName: "main",
      baseRefOid: "basebase",
      author: { login: "someone" },
      labels: [],
      reviewRequests: [],
    },
    defaultBranch: "main",
    defaultBranchOid: "basebase",
    checkRollup: [{ name: "ci / build", status: "COMPLETED", conclusion: "SUCCESS" }],
    checkRollupPageInfo: { hasNextPage: false, endCursor: null },
    reviewRequests: [],
    reviewRequestsPageInfo: { hasNextPage: false, endCursor: null },
    ...snapshotOverrides,
  };
  return {
    pullRequestSnapshot: async (): Promise<PullRequestSnapshot> => snapshot,
    reviews: async (): Promise<unknown[]> => [
      { user: { login: "sasuke" }, state: "APPROVED", commit_id: "cafebabe", submitted_at: "2025-01-01T00:00:00Z" },
      { user: { login: "tenma" }, state: "APPROVED", commit_id: "cafebabe", submitted_at: "2025-01-01T00:00:00Z" },
    ],
    reviewThreadsPage: async (): Promise<ReviewThreadPage> => ({ nodes: [], hasNextPage: false, endCursor: null }),
    timeline: async (): Promise<unknown[]> => [],
    checkRollupPage: async (): Promise<CheckRollupPage> => {
      throw new Error("checkRollupPage should not be called when hasNextPage is false");
    },
    reviewRequestsPage: async (): Promise<ReviewRequestsPage> => {
      throw new Error("reviewRequestsPage should not be called when hasNextPage is false");
    },
    fileAtRef: async (): Promise<string | null> => null,
    ...overrides,
  };
}

function stubDeps(source: PrStateSource | null): PrReadyDeps {
  return {
    now: (): string => "2025-01-01T00:00:00Z",
    executable: (): string => "/opt/nen/nen-linux-x64",
    openSource: (): { ok: true; source: PrStateSource } | { ok: false; message: string } =>
      source === null ? { ok: false, message: "no usable token" } : { ok: true, source },
    localCheckout: (): null => null,
  };
}

// ── the scenarios ───────────────────────────────────────────────────────────

const BASE = "basebase";
const OTHER_DEFAULT = "defa017";
const GATES = readFileSync(schemaPath(BANKAI_REPO, GATES_FILE), "utf8");
const UNKNOWN_KEY = JSON.stringify({ ...(JSON.parse(GATES) as object), future_gate: { on: true } }, null, 2);

/** `nen/gates.json` per commit: text, `null` (no file), or an Error the read throws. */
type GatesAt = (ref: string) => string | null | Error;

interface Scenario {
  readonly gatesAt: GatesAt;
  /** The default-branch tip GitHub names (the base is always `basebase`). */
  readonly defaultOid: string;
  readonly failingCheck?: boolean;
}

const upstream = (): Error => new Error("HTTP 502: upstream");

/** The ruling's seven non-opted-in scenarios, by golden file name. */
export const SCENARIOS: Readonly<Record<string, Scenario>> = {
  // (i) the default tip readable, declaring no version_collision.
  "i-default-readable-no-block": { gatesAt: (): string => GATES, defaultOid: BASE },
  // (ii) the default tip's read fails; the base is the same commit.
  "ii-default-unreadable-base-same": { gatesAt: upstream, defaultOid: BASE },
  // (iii) the default tip's read fails; the base is another, readable commit.
  "iii-default-unreadable-base-readable": { gatesAt: (ref): string | Error => (ref === OTHER_DEFAULT ? upstream() : GATES), defaultOid: OTHER_DEFAULT },
  // (iv) the default tip's file is malformed JSON (the base readable elsewhere).
  "iv-default-malformed": { gatesAt: (ref): string => (ref === OTHER_DEFAULT ? "{ not json" : GATES), defaultOid: OTHER_DEFAULT },
  // (v) the default tip carries a key from a newer nen, and no version_collision.
  "v-default-unknown-key": { gatesAt: (ref): string => (ref === OTHER_DEFAULT ? UNKNOWN_KEY : GATES), defaultOid: OTHER_DEFAULT },
  // (vi) no nen/gates.json at the default tip (nor at the base: one commit).
  "vi-no-gates-file": { gatesAt: (): null => null, defaultOid: BASE },
  // (vii) not ready -- a failing check -- under (ii).
  "vii-failing-check-default-unreadable": { gatesAt: upstream, defaultOid: BASE, failingCheck: true },
};

/** The stub answers every read the harness offers; `reads` records each file read, in order -- the reads main makes. */
function sourceFor(scenario: Scenario, reads: string[]): PrStateSource {
  return stubSource(
    {
      fileAtRef: async (_repo: PrRef, path: string, ref: string): Promise<string | null> => {
        reads.push(`${path}@${ref}`);
        if (path !== GATES_FILE) return null;
        const answer = scenario.gatesAt(ref);
        if (answer instanceof Error) throw answer;
        return answer;
      },
    },
    {
      defaultBranchOid: scenario.defaultOid,
      ...(scenario.failingCheck === true
        ? { checkRollup: [{ name: "ci / build", status: "COMPLETED", conclusion: "FAILURE" }] }
        : {}),
    },
  );
}

/** One invocation's whole observable outcome. */
export interface Run {
  readonly code: number;
  readonly out: string;
  readonly err: string;
  /** Every file read at a commit, in order. The stub offers none of the version-collision reads at all. */
  readonly reads: readonly string[];
}

/** Each scenario under `--json`, plain and `--explain`. */
export interface ScenarioRuns {
  readonly json: Run;
  readonly plain: Run;
  readonly explain: Run;
}

/** Where this process put the run-specific paths: replaced in every output, on both sides alike. */
interface Places {
  readonly gates: string;
  readonly root: string;
}

let places: Places | null = null;

/** `path` as the product may print it: resolved (as `--gates` is), JSON-escaped, raw, slash-separated; longest first. */
function renderings(path: string): string[] {
  const forms = new Set<string>();
  for (const base of [resolve(path), path]) {
    forms.add(JSON.stringify(base).slice(1, -1));
    forms.add(base);
    forms.add(base.replaceAll("\\", "/"));
  }
  return [...forms].sort((a, b): number => b.length - a.length);
}

function placesOnce(): Places {
  if (places === null) {
    const dir = makeTempDir("nen-663-golden-gates-");
    const gates = join(dir, "gates.json");
    writeFileSync(gates, GATES);
    places = { gates, root: makeTempDir("nen-663-golden-root-") };
  }
  return places;
}

/**
 * The ONLY normalisation, applied identically to main's output and this
 * branch's: the two temp paths (run-specific), the build's own version (the
 * generator and the "This is nen X" sentence), and the one `version_collision
 * (nen >= …)` entry in the list of keys a build reads -- a fact about which
 * keys the binary knows, printed inside main's unknown-key refusal, never a
 * behaviour. On main every replacement but the paths is a no-op or the same
 * version string.
 */
export function normalise(text: string): string {
  const { gates, root } = placesOnce();
  let out = text;
  // Each temp path in every rendering the product can print: JSON-escaped
  // first (a Windows `\` is doubled inside --json), then as given, then with
  // forward slashes -- the exact runtime strings, never a separator pattern.
  // On POSIX all three renderings are one string.
  for (const [path, mark] of [[gates, "<GATES>"], [root, "<ROOT>"]] as const) {
    for (const form of renderings(path)) out = out.replaceAll(form, mark);
  }
  return out
    .replaceAll(`"version": "${VERSION}"`, `"version": "<VERSION>"`)
    .replaceAll(`This is nen ${VERSION}`, "This is nen <VERSION>")
    .replace(/, version_collision \(nen >= [0-9.]+\)/g, "");
}

async function once(scenario: Scenario, booleans: readonly string[]): Promise<Run> {
  const { gates, root } = placesOnce();
  const out: string[] = [];
  const err: string[] = [];
  const io: Io = { out: (line): void => void out.push(line), err: (line): void => void err.push(line) };
  const input: PrReadyInput = {
    positionals: ["pr", "ready", "9"],
    values: { "gh-repo": "acme/widget", gates },
    booleans: new Set(booleans),
    repoFlag: root,
  };
  const reads: string[] = [];
  const code = await prReady(input, io, stubDeps(sourceFor(scenario, reads)));
  return { code, out: normalise(out.join("\n")), err: normalise(err.join("\n")), reads };
}

export async function runScenario(name: string): Promise<ScenarioRuns> {
  const scenario = SCENARIOS[name];
  if (scenario === undefined) throw new Error(`no scenario '${name}'`);
  return { json: await once(scenario, ["json"]), plain: await once(scenario, []), explain: await once(scenario, ["explain"]) };
}

/** The golden files one scenario writes: the JSON report, the two human renderings, and every exit code, stderr and file read. */
export function goldenFiles(name: string, runs: ScenarioRuns): Record<string, string> {
  return {
    [`${name}.json`]: `${runs.json.out}\n`,
    [`${name}.txt`]: `${runs.plain.out}\n`,
    [`${name}.explain.txt`]: `${runs.explain.out}\n`,
    [`${name}.exit.json`]: `${JSON.stringify(
      {
        json: { code: runs.json.code, err: runs.json.err, reads: runs.json.reads },
        plain: { code: runs.plain.code, err: runs.plain.err, reads: runs.plain.reads },
        explain: { code: runs.explain.code, err: runs.explain.err, reads: runs.explain.reads },
      },
      null,
      2,
    )}\n`,
  };
}
